Your expense tracker for October 2026 is below. Add an item, pick a category and set a budget to see the bars and balance update. Entries stay only while this page is open.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:14px;background:#f7f7f5;color:#222}
h2{margin:0 0 10px;font-size:18px}
.row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:7px;border:1px solid #ccc;border-radius:6px;font-size:14px}
input{flex:1;min-width:90px}
button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
.card{background:#fff;border-radius:10px;padding:10px;margin-bottom:10px;box-shadow:0 1px 3px #0001}
.big{font-size:22px;font-weight:600}
.bar{height:8px;background:#e6e6e2;border-radius:4px;margin:3px 0 8px}
.bar i{display:block;height:100%;background:#2f7d5b;border-radius:4px}
.item{display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid #eee;font-size:14px}
.item button{background:#c0392b;padding:2px 8px;margin-left:8px}
.over{color:#c0392b}
small{color:#777}
</style></head><body>
<h2>Expenses: October 2026</h2>
<div class="card">
<div class="row"><input id="bud" type="number" placeholder="Monthly budget (₹)" oninput="draw()"></div>
<div class="big" id="tot">₹0</div>
<small id="left">Set a budget to see what is left.</small>
</div>
<div class="card">
<div class="row">
<input id="nm" placeholder="What for?">
<input id="am" type="number" placeholder="Amount (₹)">
</div>
<div class="row">
<select id="cat"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Other</option></select>
<button onclick="add()">Add</button>
</div>
</div>
<div class="card"><b>By category</b><div id="cats"></div></div>
<div class="card"><b>All items</b><div id="list"><small>Nothing yet.</small></div></div>
<script>
var items=[];
function inr(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
function add(){
var n=document.getElementById("nm").value.trim()||"Item";
var a=parseFloat(document.getElementById("am").value);
if(!(a>0))return;
items.push({n:n,a:a,c:document.getElementById("cat").value});
document.getElementById("nm").value="";
document.getElementById("am").value="";
draw();
}
function del(i){items.splice(i,1);draw()}
function draw(){
var t=0,by={};
items.forEach(function(x){t+=x.a;by[x.c]=(by[x.c]||0)+x.a});
document.getElementById("tot").textContent=inr(t)+" spent";
var b=parseFloat(document.getElementById("bud").value);
var l=document.getElementById("left");
if(b>0){
if(t>b){l.innerHTML="<span class='over'>Over budget by "+inr(t-b)+"</span>"}
else{l.textContent=inr(b-t)+" left of "+inr(b)}
}else{l.textContent="Set a budget to see what is left."}
var c="";
Object.keys(by).forEach(function(k){
var p=t?by[k]/t*100:0;
c+="<div>"+k+" <small>"+inr(by[k])+" ("+Math.round(p)+"%)</small></div><div class='bar'><i style='width:"+p+"%'></i></div>";
});
document.getElementById("cats").innerHTML=c||"<small>Nothing yet.</small>";
var h="";
items.forEach(function(x,i){
h+="<div class='item'><span>"+x.n.replace(/</g,"&lt;")+" <small>"+x.c+"</small></span><span>"+inr(x.a)+"<button onclick='del("+i+")'>x</button></span></div>";
});
document.getElementById("list").innerHTML=h||"<small>Nothing yet.</small>";
}
draw();
</script>
</body></html>
```
